module ip_checksum #(parameter SIZE = 8) (  
    input wire clk,  
    input wire reset,  
    input wire [15:0] data_in,  
    input wire valid,  
    output reg [15:0] checksum,  
    output reg done  
);  
    reg [15:0] sum;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            sum <= 16'b0;  
            count <= 4'b0;  
            done <= 1'b0;  
            checksum <= 16'b0;  
        end else if (valid) begin  
            sum <= sum + data_in;  
            count <= count + 1;  
            if (count == SIZE - 1) begin  
                checksum <= ~sum;  
                done <= 1'b1;  
            end  
        end  
    end  
endmodule

