module fractional_n_pll (
    input wire ref_clk,          // Reference clock input
    input wire rst,             // Reset signal
    input wire [7:0] frac_div,  // Fractional divide value
    output reg out_clk          // Output clock
);
    reg [7:0] counter;          // Counter for clock division
    reg [31:0] phase_acc;       // Phase accumulator for fractional control
    reg vco_clk;                // VCO output

    always @(posedge ref_clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            phase_acc <= 0;
            out_clk <= 0;
            vco_clk <= 0;
        end else begin
            // Update phase accumulator
            phase_acc <= phase_acc + frac_div;
            // Generate VCO clock based on phase accumulator
            if (phase_acc[31:24] >= 8'hFF) begin
                vco_clk <= ~vco_clk; // Toggle VCO clock
                phase_acc <= phase_acc - 8'hFF; // Adjust phase accumulator
            end

            // Generate output clock based on counter
            counter <= counter + 1;
            if (counter >= frac_div) begin
                out_clk <= vco_clk; // Output the VCO clock
                counter <= 0; // Reset counter
            end
        end
    end
endmodule

