module MersenneTwister (
    input wire clk,
    input wire reset,
    output reg [31:0] random_number
);
    reg [31:0] mt[0:623]; // state vector of 624 words
    reg [9:0] index;      // index for mt
    integer i;

    initial begin
        index = 0;
        // Seed the generator with a constant value or a seed input
        mt[0] = 32'h12345678;
        for (i = 1; i < 624; i = i + 1) begin
            mt[i] = (1812433253 * (mt[i-1] ^ (mt[i-1] >> 30)) + i);
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            index <= 0;
        end else begin
            if (index == 0) begin
                for (i = 0; i < 624; i = i + 1) begin
                    mt[i] = mt[i] ^ (mt[(i+1) % 624] >> 1) ^ (32'h9908b0df & {32{mt[i] & 1'b1}});
                end
            end
            random_number <= mt[index];
            index <= (index + 1) % 624;
        end
    end
endmodule

