module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire kick,  
    output reg expired  
);  
    parameter TIMEOUT = 10;  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            expired <= 0;  
        end else begin  
            if (kick) begin  
                counter <= 0;  
                expired <= 0;  
            end else if (counter < TIMEOUT) begin  
                counter <= counter + 1;  
            end  
            if (counter == TIMEOUT) begin  
                expired <= 1;  
            end  
        end  
    end  
endmodule

