module timer_8bit(  
    input clk,  
    input reset,  
    output reg [7:0] count  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            count <= 8'b00000000;  
        else if (count < 8'b11111111)  
            count <= count + 1;  
        else  
            count <= 8'b00000000;  
    end  
endmodule

