module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire timeout_enable,  
    output reg timeout_condition  
);  

    parameter TIMEOUT_VALUE = 8'd100;  // Set the desired timeout value  
    reg [7:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 8'd0;  
            timeout_condition <= 1'b0;  
        end else if (timeout_enable) begin  
            if (counter < TIMEOUT_VALUE) begin  
                counter <= counter + 1;  
                timeout_condition <= 1'b0;  
            end else begin  
                timeout_condition <= 1'b1;  
            end  
        end  
    end  
endmodule

