module serializer(input clk,  
                  input enable,  
                  input [15:0] parallel_in,  
                  output reg serial_out);  
    reg [3:0] count;  
    always @(posedge clk or negedge enable) begin  
        if (!enable) begin  
            count <= 0;  
            serial_out <= 0;  
        end else if (count < 16) begin  
            serial_out <= parallel_in[15 - count];  
            count <= count + 1;  
        end  
    end  
endmodule

