module fractional_n_pll #(parameter N = 8, M = 8) (  
    input wire clk_in,  
    input wire reset,  
    input wire [N-1:0] fractional_multiplier,  
    output reg clk_out  
);  

    reg [N-1:0] phase_accumulator;  
    reg [N-1:0] vco_output;  

    // Phase accumulator  
    always @(posedge clk_in or posedge reset) begin  
        if (reset)  
            phase_accumulator <= 0;  
        else  
            phase_accumulator <= phase_accumulator + fractional_multiplier;  
    end  

    // VCO output generation  
    always @(posedge clk_in or posedge reset) begin  
        if (reset)  
            vco_output <= 0;  
        else  
            vco_output <= phase_accumulator[N-1:0];  // Simulate VCO output  
    end  

    // Generate output clock based on VCO output  
    always @(posedge clk_in or posedge reset) begin  
        if (reset)  
            clk_out <= 0;  
        else  
            clk_out <= vco_output[N-1];  // Simple toggle for output clock  
    end  
endmodule

