module bfs_tree_traverse (  
    input clk,  
    input reset,  
    input [6:0] tree, // 7 nodes for a binary tree  
    output reg [6:0] bfs_output // BFS output  
);  
    reg [2:0] state; // Current state  
    reg [6:0] queue; // Queue for BFS, 7 bits  
    reg [2:0] front, rear; // Queue pointers  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bfs_output <= 7'b0;  
            queue <= 7'b0;  
            front <= 3'b0;  
            rear <= 3'b0;  
            state <= 3'b0;  
        end else begin  
            case (state)  
                3'b000: begin // Initialize  
                    queue <= {tree[6:0]}; // Load tree into queue  
                    bfs_output <= 7'b0;  
                    front <= 3'b0;  
                    rear <= 3'b0;  
                    state <= 3'b001;  
                end  
                3'b001: begin // Process queue  
                    if (front <= rear) begin  
                        bfs_output[front] <= queue[front]; // Output current node  
                        front <= front + 1;  
                    end else begin  
                        state <= 3'b010; // Move to completed state  
                    end  
                end  
                3'b010: begin  
                    // Completed BFS traversal  
                    state <= 3'b010;  
                end  
            endcase  
        end  
    end  
endmodule

