module uart_transmitter (  
    input wire clk,  
    input wire rst,  
    input wire send,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  
    reg [3:0] bit_index;  
    reg [9:0] shift_reg;  
    reg [15:0] baud_counter;  
    parameter BAUD_RATE = 104; // Example value, adjust according to clock frequency  
    parameter IDLE = 1'b1, TRANSMIT = 1'b0;  
    reg state, next_state;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            busy <= 0;  
            tx <= 1;  
            bit_index <= 0;  
        end else begin  
            state <= next_state;  
            if (state == TRANSMIT) begin  
                if (baud_counter == BAUD_RATE) begin  
                    baud_counter <= 0;  
                    if (bit_index < 10) begin  
                        tx <= shift_reg[bit_index];  
                        bit_index <= bit_index + 1;  
                    end else begin  
                        busy <= 0;  
                        bit_index <= 0;  
                    end  
                end else begin  
                    baud_counter <= baud_counter + 1;  
                end  
            end  
        end  
    end  

    always @(*) begin  
        next_state = state;  
        if (send && !busy) begin  
            busy = 1;  
            shift_reg = {1'b1, data_in, 1'b0}; // Start bit, data bits, stop bit  
            next_state = TRANSMIT;  
        end  
    end  
endmodule

