module watchdog_timer (
    input wire clk,
    input wire reset,
    input wire async_reset,
    input wire [3:0] timeout,
    output reg out
);
    reg [3:0] counter;

    always @(posedge clk or posedge async_reset) begin
        if (async_reset) begin
            out <= 0;
            counter <= 0;
        end else if (reset) begin
            out <= 1;
            counter <= 0;
        end else if (counter < timeout) begin
            counter <= counter + 1;
            out <= 1;
        end else begin
            out <= 0;
        end
    end
endmodule

