module bfs #(parameter N = 5) (  
    input clk,  
    input rst,  
    input [N*N-1:0] adj_matrix,  
    input [2:0] start_node,  
    output reg [N-1:0] visited,  
    output reg [N-1:0] traversal_order  
);  
    reg [N-1:0] queue;  
    reg [2:0] head;  
    reg [2:0] tail;  
    integer i;  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            visited <= 0;  
            traversal_order <= 0;  
            queue <= 0;  
            head <= 0;  
            tail <= 0;  
        end else begin  
            if (head < N && visited[head] == 0) begin  
                visited[head] <= 1;  
                traversal_order[head] <= 1;  
                for (i = 0; i < N; i = i + 1) begin  
                    if (adj_matrix[head * N + i] && !visited[i]) begin  
                        queue[tail] <= i;  
                        tail <= tail + 1;  
                    end  
                end  
                head <= head + 1;  
            end  
        end  
    end  
endmodule

