module fir_filter (
    input [3:0] x0, // current input
    input [3:0] x1, // previous input
    input [3:0] x2, // two inputs ago
    input [3:0] x3, // three inputs ago
    output [7:0] y // output
);

assign y = (1*x0) + (2*x1) + (1*x2) + (1*x3);

endmodule

module nor_gate (
    input wire a,
    input wire b,
    input wire c,
    input wire d,
    output wire y
);
    assign y = ~(a | b | c | d);
endmodule

module rrt_controller #(parameter STEP_SIZE = 4) (  
    input clk,  
    input reset,  
    input [7:0] x,  
    input [7:0] y,  
    input [7:0] tx,  
    input [7:0] ty,  
    output reg [7:0] nx,  
    output reg [7:0] ny,  
    output reg done  
);  
    reg [1:0] state;  
    localparam IDLE = 2'b00, MOVE = 2'b01, DONE = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            nx <= x;  
            ny <= y;  
            done <= 0;  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (nx != tx || ny != ty) begin  
                        state <= MOVE;  
                        done <= 0;  
                    end else begin  
                        state <= DONE;  
                        done <= 1;  
                    end  
                end  
                MOVE: begin  
                    if (nx < tx)  
                        nx <= nx + STEP_SIZE;  
                    else if (nx > tx)  
                        nx <= nx - STEP_SIZE;  

                    if (ny < ty)  
                        ny <= ny + STEP_SIZE;  
                    else if (ny > ty)  
                        ny <= ny - STEP_SIZE;  

                    if (nx == tx && ny == ty) begin  
                        state <= DONE;  
                        done <= 1;  
                    end  
                end  
                DONE: begin  
                    // Stay in DONE state  
                end  
            endcase  
        end  
    end  
endmodule

