module i2c_master (
    input clk,
    input reset,
    input [6:0] slave_addr,
    input [7:0] data_in,
    input start,
    input read, // 1 for read, 0 for write
    output reg sda,
    output reg scl,
    output reg [7:0] data_out,
    output reg ready
);

    reg [3:0] state;
    reg [3:0] bit_cnt;
    reg [7:0] data_buffer;

    localparam IDLE = 4'b0000,
               START = 4'b0001,
               SEND_ADDR = 4'b0010,
               SEND_DATA = 4'b0011,
               RECEIVE_DATA = 4'b0100,
               STOP = 4'b0101;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            sda <= 1;
            scl <= 1;
            ready <= 1;
            bit_cnt <= 0;
            data_out <= 0;
            data_buffer <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        sda <= 0; // Start condition
                        scl <= 1;
                        state <= START;
                        ready <= 0;
                    end
                end
                START: begin
                    scl <= 0;
                    state <= SEND_ADDR;
                end
                SEND_ADDR: begin
                    sda <= {slave_addr, 1'b0}; // Write operation
                    if (bit_cnt < 8) begin
                        scl <= ~scl;
                        bit_cnt <= bit_cnt + 1;
                    end else begin
                        bit_cnt <= 0;
                        state <= SEND_DATA;
                    end
                end
                SEND_DATA: begin
                    sda <= data_in;
                    if (bit_cnt < 8) begin
                        scl <= ~scl;
                        bit_cnt <= bit_cnt + 1;
                    end else begin
                        bit_cnt <= 0;
                        state <= STOP;
                    end
                end
                STOP: begin
                    sda <= 1; // Stop condition
                    scl <= 1;
                    state <= IDLE;
                    ready <= 1;
                end
            endcase
        end
    end
endmodule

module PLL_8x (  
    input wire clk_ref,  
    input wire reset,  
    output reg clk_out  
);  
    reg [2:0] state;  
    reg [2:0] next_state;  
    reg [2:0] counter;  

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            state <= 3'b000;  
            counter <= 3'b000;  
            clk_out <= 0;  
        end else begin  
            state <= next_state;  
            if (state == 3'b111) begin  
                clk_out <= ~clk_out;  
                counter <= 3'b000;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  

    always @(*) begin  
        case (state)  
            3'b000: next_state = 3'b001;  
            3'b001: next_state = 3'b010;  
            3'b010: next_state = 3'b011;  
            3'b011: next_state = 3'b100;  
            3'b100: next_state = 3'b101;  
            3'b101: next_state = 3'b110;  
            3'b110: next_state = 3'b111;  
            3'b111: next_state = 3'b000;  
            default: next_state = 3'b000;  
        endcase  
    end  
endmodule

