module SR_FF (  
    input wire S,  
    input wire R,  
    input wire CLK,  
    output reg Q  
);  
    always @(posedge CLK) begin  
        if (S && R)  
            Q <= 1'bx; // Invalid state  
        else if (S)  
            Q <= 1; // Set  
        else if (R)  
            Q <= 0; // Reset  
        // else Q retains its state  
    end  
endmodule

