module fft_4point (
    input signed [7:0] x0_real, x0_imag,
    input signed [7:0] x1_real, x1_imag,
    input signed [7:0] x2_real, x2_imag,
    input signed [7:0] x3_real, x3_imag,
    output signed [7:0] y0_real, y0_imag,
    output signed [7:0] y1_real, y1_imag,
    output signed [7:0] y2_real, y2_imag,
    output signed [7:0] y3_real, y3_imag
);
    // FFT calculations
    wire signed [8:0] w0_real, w0_imag, w1_real, w1_imag;
    wire signed [7:0] x1_real_w, x1_imag_w, x2_real_w, x2_imag_w;

    // Twiddle factors for 4-point FFT
    assign w1_real =  0; // cos(π/2)
    assign w1_imag = -1; // sin(π/2)

    assign x1_real_w = x1_real + (w1_real * x1_real - w1_imag * x1_imag);
    assign x1_imag_w = x1_imag + (w1_imag * x1_real + w1_real * x1_imag);

    assign x2_real_w = x2_real + (w1_real * x2_real - w1_imag * x2_imag);
    assign x2_imag_w = x2_imag + (w1_imag * x2_real + w1_real * x2_imag);

    // Output calculations (FFT results)
    assign y0_real = x0_real + x1_real_w + x2_real_w + x3_real;
    assign y0_imag = x0_imag + x1_imag_w + x2_imag_w + x3_imag;

    assign y1_real = x0_real - x1_real_w + x2_real_w - x3_real;
    assign y1_imag = x0_imag - x1_imag_w + x2_imag_w - x3_imag;

    assign y2_real = x0_real - x1_real_w - x2_real_w + x3_real;
    assign y2_imag = x0_imag - x1_imag_w - x2_imag_w + x3_imag;

    assign y3_real = x0_real + x1_real_w - x2_real_w - x3_real;
    assign y3_imag = x0_imag + x1_imag_w - x2_imag_w - x3_imag;

endmodule

