module sample_rate_converter (
    input wire clk,
    input wire rst,
    input wire [15:0] sample_in,
    input wire sample_valid,
    output reg [15:0] sample_out,
    output reg sample_out_valid
);

reg [1:0] state;
reg [15:0] samples [0:2]; // Store 3 samples from 44.1 kHz
reg [3:0] count;
integer i;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        state <= 0;
        count <= 0;
        sample_out_valid <= 0;
        sample_out <= 0;
    end else begin
        case (state)
            0: begin // Waiting for valid input
                if (sample_valid) begin
                    samples[count] <= sample_in;
                    count <= count + 1;
                    if (count == 2) begin
                        state <= 1;
                        count <= 0;
                    end
                end
            end
            1: begin // Output samples
                if (count < 4) begin
                    case (count)
                        0: sample_out <= samples[0];
                        1: sample_out <= (samples[0] + samples[1]) >> 1; // Interpolation
                        2: sample_out <= samples[1];
                        3: sample_out <= (samples[1] + samples[2]) >> 1; // Interpolation
                    endcase
                    sample_out_valid <= 1;
                    count <= count + 1;
                end else begin
                    state <= 0;
                    sample_out_valid <= 0;
                end
            end
        endcase
    end
end

endmodule

