module Chebyshev_Filter (
    input clk,
    input rst,
    input [4:0] x_in,
    output reg [4:0] y_out
);
    reg [4:0] x [0:2]; // state registers for inputs
    reg [4:0] b [0:2]; // filter coefficients
    integer i;

    // Chebyshev filter coefficients (example values)
    initial begin
        b[0] = 5'b00001; // Coefficient for x[n]
        b[1] = 5'b00010; // Coefficient for x[n-1]
        b[2] = 5'b00011; // Coefficient for x[n-2]
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y_out <= 5'b00000;
            for (i = 0; i < 3; i = i + 1) begin
                x[i] <= 5'b00000;
            end
        end else begin
            // Shift input data
            x[2] <= x[1];
            x[1] <= x[0];
            x[0] <= x_in;

            // Output calculation based on filter coefficients
            y_out <= (b[0] * x[0]) + (b[1] * x[1]) + (b[2] * x[2]);
        end
    end
endmodule

