module pulse_generator (  
    input clk,  
    input reset,  
    input trigger,  
    input [3:0] pulse_width,  
    output reg pulse  
);  

reg [3:0] count;  
reg generating;  

always @(posedge clk or posedge reset) begin  
    if (reset) begin  
        pulse <= 0;  
        count <= 0;  
        generating <= 0;  
    end else begin  
        if (trigger && !generating) begin  
            generating <= 1;  
            count <= pulse_width;  
            pulse <= 1;  
        end else if (generating) begin  
            if (count > 0) begin  
                count <= count - 1;  
            end else begin  
                generating <= 0;  
                pulse <= 0;  
            end  
        end  
    end  
end  
endmodule

